class Solution
{
public:
    vector< string>generatePalindromes(string s)
    {
        map< char, int>freq;
        for (char c : s)++freq[c];
        int odd = 0;
        string half, mid;
        for (auto&p : freq)
        {
            if (p.second % 2)
            {
                ++odd;
                mid = string(1, p.first);
            }
            half.append(p.second / 2, p.first);
        }
        if (odd >1) return { };
        vector< string>ans;
        do
        {
            string right = half;
            reverse(right.begin(), right.end());
            ans.push_back(half + mid + right);
        }
        while (next_permutation(half.begin(), half.end()));
        return ans;
    }
};
